  RETURNING "id" INTO mt_id;

  INSERT INTO "lesen_teil1_exercises"
    ("contentRevision", "label", "instruction", "modelltest_id")
  VALUES ('b2-modelltest-1-lesen-teil1-v1', 'Leseverstehen, Teil 1', 'Lesen Sie zuerst die zehn Überschriften. Lesen Sie dann die fünf Texte und entscheiden Sie,
welche Überschrift (a–j) am besten zu welchem Text (1–5) passt.
Tragen Sie Ihre Lösungen in den Antwortbogen bei den Aufgaben 1–5 ein.', mt_id)
  ON CONFLICT ("modelltest_id") DO UPDATE SET
    "contentRevision" = EXCLUDED."contentRevision",
    "label" = EXCLUDED."label",
    "instruction" = EXCLUDED."instruction"
  RETURNING "id" INTO seed_exercise_id;

  DELETE FROM "lesen_teil1_texts" WHERE "exerciseId" = seed_exercise_id;
  DELETE FROM "lesen_teil1_titles" WHERE "exerciseId" = seed_exercise_id;
  INSERT INTO "lesen_teil1_titles" ("exerciseId", "content", "sortOrder") VALUES
    (seed_exercise_id, 'Am Strand im Dienst – mehr Sicherheit für Urlauber', 0),
    (seed_exercise_id, 'Bäder, Seen und Natur – im hessischen Paradies', 1),
    (seed_exercise_id, 'Freiheit und Natur – nach sechs Wochen harter Arbeit', 2),
    (seed_exercise_id, 'Jugendliche arbeiten für Jugendliche', 3),
    (seed_exercise_id, 'Kinderarbeit in Deutschland: Jugendliche werden zur Arbeit gezwungen', 4),
    (seed_exercise_id, 'Nach harter Arbeit durch nordische Gewässer', 5),
    (seed_exercise_id, 'Schaden an Kreuzfahrtschiff verhindert Weiterfahrt', 6),
    (seed_exercise_id, 'Urlaub an deutschen Seen immer gefährlicher', 7),
